RECORDS = [('固有免疫与适应性免疫', '免疫系统组成', '免疫系统的组成；固有免疫与适应性免疫原理', '固有免疫依赖屏障、模式识别及效应细胞等快速反应，适应性免疫依赖具有多样受体的淋巴细胞和克隆选择。两者相互作用，经典适应性应答具有特异性记忆。', ['能比较两类免疫的识别方式。', '能说明两者合作而非独立运作。'], Q('克隆性淋巴细胞应答和特异性免疫记忆最典型地属于哪一体系？', '适应性免疫', ['单纯皮肤机械屏障', '补体的非特异性效应', '中性粒细胞的模式识别和吞噬'], 'T、B淋巴细胞的克隆性应答及记忆是适应性免疫的重要特征。'), Q('病原相关模式被识别后促进抗原呈递及淋巴细胞活化，主要说明什么？', '固有免疫可以启动和塑造适应性免疫', ['适应性免疫完全不受固有免疫信号影响', '模式识别受体对每种抗原都像抗体一样随机重排', '所有呈递功能都必须等抗体形成后才开始'], '先天识别产生的细胞活化与信号为后续适应性应答提供重要条件。')), ('免疫器官与淋巴细胞循环', '免疫系统组成', '免疫系统的组成', '中枢免疫器官为淋巴细胞发育成熟提供条件，外周免疫器官为抗原与成熟淋巴细胞相遇及应答提供场所。T细胞主要在胸腺成熟，B细胞在人体骨髓中发育成熟。', ['能区分中枢与外周免疫器官。', '能关联T、B细胞的成熟场所。'], Q('人体T细胞发育成熟的重要中枢免疫器官是什么？', '胸腺', ['脾', '淋巴结', '扁桃体'], '胸腺提供T细胞分化和选择所需微环境；扁桃体、脾和淋巴结主要属于外周淋巴组织。'), Q('淋巴结内抗原与成熟淋巴细胞相遇并产生应答，体现了哪种主要功能？', '外周免疫应答的组织平台', ['未成熟T细胞在胸腺中受选择的主要场所', '所有血细胞分化成熟的主要场所', '在没有抗原时只储存细胞而不能形成免疫应答'], '外周淋巴器官便于抗原、抗原呈递细胞和淋巴细胞有序相遇。'), [('med_anatomy_010', '淋巴器官和回流结构有助于理解免疫细胞循环', 'soft')]), ('抗原、表位与免疫原性', '免疫识别', '免疫系统的组成与抗原识别主题', '抗原表位是被免疫受体识别的局部结构，抗原性与诱导应答的免疫原性需区分。半抗原可被相应抗体识别，但通常需与适当载体结合后才有效诱导应答。', ['能区分抗原性与免疫原性。', '能解释表位和完整抗原的关系。'], Q('抗体或相应受体直接识别的抗原局部结构叫什么？', '表位', ['抗体的Fc片段', '补体膜攻击复合物', '抗体的恒定区类别标志'], '一个抗原可具有多个表位，不同受体的识别特异性可不同。'), Q('某小分子能结合既有抗体，但单独应用难以诱导相应抗体形成，最符合哪个概念？', '半抗原的特征', ['它具有完整免疫原性而没有抗原性', '它必然是能独立诱导相同应答的完全抗原', '它与抗体结合证明抗原性和免疫原性完全等同'], '半抗原体现可被识别与可独立诱导应答之间的区别，通常需合适载体配合。'), [(1, '需先区分免疫识别与后续应答')]), ('抗体结构、类别与效应', '免疫识别', '免疫系统的组成与抗体主题', '抗体由B细胞谱系分化的浆细胞分泌，其可变区参与抗原识别，恒定区与类别及效应功能相关。不同免疫球蛋白具有不同分布和功能，不能把抗体存在直接等同于完全保护。', ['能区分抗原结合与效应功能部位。', '能说明抗体来源与类别差异。'], Q('大量分泌抗体的效应细胞主要是哪类？', '浆细胞', ['中性粒细胞', '细胞毒性T细胞', '自然杀伤细胞'], '活化B细胞可分化为浆细胞，承担抗体分泌。'), Q('某抗体保留抗原结合能力，但Fc介导的效应改变，这说明什么？', '抗原识别与部分效应功能可由不同结构区域承担', ['Fc是唯一抗原识别位点，因此抗原识别必然同时消失', '可变区只决定补体活化，不参与结合抗原', '所有抗体片段都必须完整保留才能发生任何抗原结合'], 'Fab区域包含抗原结合位点，Fc区域参与受体结合和补体等效应联系。'), [(3, '抗体结合的特异性建立在表位识别之上')]), ('补体活化与效应调节', '固有免疫', '固有免疫应答的原理', '补体系统可经不同途径活化，产生调理、炎症介导及膜攻击等效应。调节蛋白限制过度活化与自身损伤，补体功能不能简化为只依赖抗体或只杀菌。', ['能举例说明补体的不同效应。', '能解释补体调节的必要性。'], Q('补体C3b的重要作用之一是什么？', '调理作用，促进吞噬识别', ['直接组成全部膜攻击复合物的孔道', '单独承担T细胞受体的抗原识别', '直接完成抗体重链类别转换'], 'C3b可附着于靶表面，促进具有相应受体的细胞识别和清除。'), Q('为何补体活化需要宿主调节机制？', '限制自身组织表面的异常或过度活化', ['使宿主所有补体成分始终不能活化', '因为补体只在抗体结合后才能通过唯一途径活化', '使补体活化不再需要任何表面或酶促反应条件'], '补体效应具有放大性，调节有助于区分和限制对宿主组织的损伤。'), [(1, '补体是固有免疫重要效应系统，可与适应性免疫相连')]), ('抗原加工、MHC与呈递', '免疫识别', '适应性免疫应答的原理', 'T细胞通常识别MHC分子呈递的肽。经典途径中，MHCⅠ主要呈递内源性抗原给CD8 T细胞，MHCⅡ主要呈递外源性抗原给CD4 T细胞；还存在交叉呈递等情况。', ['能比较经典MHCⅠ与Ⅱ呈递途径。', '能区分经典规律与特殊呈递情况。'], Q('经典抗原呈递中，CD4 T细胞主要识别哪类分子呈递的肽？', 'MHCⅡ类分子', ['MHCⅠ类分子', '抗体游离的Fc片段', '补体C3b分子'], 'CD4与MHCⅡ限制性识别相联系；CD8通常与MHCⅠ相联系。'), Q('树突状细胞把摄取的外源性抗原经MHCⅠ呈递给CD8 T细胞，这称为什么？', '交叉呈递', ['经典外源性抗原经MHCⅡ呈递', 'B细胞的抗体类别转换', '胸腺中的阴性选择'], '交叉呈递使外源性抗原进入MHCⅠ呈递通路，说明不能把经典来源规律理解为绝无例外。'), [(3, '先明确抗原与表位，才能讨论其加工和呈递')]), ('T细胞活化与效应分工', '适应性免疫', '适应性免疫应答的原理', '初始T细胞有效活化通常需抗原识别、共刺激及细胞因子等信号。CD4 T细胞参与辅助和调节，CD8效应T细胞可杀伤相应靶细胞，效应由受体识别及局部环境限定。', ['能说明初始T细胞活化的多信号需求。', '能比较CD4与CD8的典型效应。'], Q('有效活化初始T细胞时，除特异性抗原识别外通常还需要什么？', '适当的共刺激等信号', ['只需要T细胞受体结合，不受任何共刺激影响', '必须先由T细胞分泌抗体', '必须先发生抗体重链类别转换'], '初始T细胞活化通常依赖多种协同信号，单一识别信号不一定产生完整应答。'), Q('某效应细胞通过识别靶细胞MHCⅠ相关抗原并诱导其死亡发挥作用，最符合哪类细胞？', '细胞毒性CD8 T细胞', ['分泌抗体的浆细胞', '主要通过模式识别直接吞噬的中性粒细胞', '只依据缺失自身信号进行识别的自然杀伤细胞'], '典型细胞毒性T细胞通过抗原特异性识别参与清除受感染或异常靶细胞。'), [(6, 'T细胞效应识别需要先理解MHC呈递')]), ('B细胞应答、类别转换与记忆', '适应性免疫', '适应性免疫应答的原理', 'B细胞识别抗原后可形成浆细胞和记忆细胞。T依赖性应答中可发生亲和力成熟和抗体类别转换；类别转换改变重链恒定区，不等于任意更换原有抗原特异性。', ['能区分浆细胞与记忆B细胞。', '能区分类别转换与亲和力成熟。'], Q('抗体类别转换主要改变抗体重链的哪个部分？', '恒定区', ['可变区的抗原结合特异性由此随机完全替换', '轻链恒定区发生重链类别交换', '抗体分子上的MHC类别'], '类别转换改变重链恒定区及相应效应功能，抗原结合特异性并非由此任意更换。'), Q('同一抗原再次刺激后，应答比初次通常更快、更强，其重要基础是什么？', '先前应答形成的记忆淋巴细胞', ['所有抗原本身都获得了更高的免疫原性', '抗体类别转换使所有细胞永久处于同一激活状态', '补体浓度升高是唯一且不依赖抗原特异性的原因'], '免疫记忆使后续特异应答的速度、规模和质量可发生变化，但实际保护仍依情境而定。'), [(4, '理解抗体结构才能区分类别和结合特性'), (7, 'T细胞辅助参与T依赖性B细胞应答', 'soft')]), ('免疫耐受与自身免疫', '免疫病理', '免疫相关性疾病的发生原理', '免疫耐受限制对特定抗原的不当应答，可在淋巴细胞发育或外周调节中形成。耐受失衡可能参与自身免疫，但自身抗体阳性与具体自身免疫病不能简单画等号。', ['能区分中枢与外周耐受。', '能说明检测标志物与疾病判定的差别。'], Q('在淋巴细胞发育场所删除或改变强自身反应性克隆，主要属于哪类机制？', '中枢耐受', ['外周无能状态的全部同义词', '初始淋巴细胞在外周的克隆扩增', '炎症局部的补体调理作用'], '中枢耐受发生于发育成熟相关场所，外周还存在多种补充调节机制。'), Q('仅发现某自身抗体阳性，最严谨的认识是什么？', '需结合检测特性及其他临床证据解释，不能单项确诊', ['任何自身抗体阳性均等于同一种疾病', '抗体阳性可直接决定全部用药', '所有健康人绝不可能出现任何自身抗体'], '自身抗体的意义取决于具体检测、背景与其他证据，单个指标不足以完成疾病判断。'), [(7, 'T细胞活化规则有助于理解耐受形成'), (8, 'B细胞应答与自身抗体形成相连', 'soft')]), ('超敏反应的机制分类', '免疫病理', '免疫相关性疾病的发生原理', '超敏反应是免疫应答引起组织损伤或功能异常的情况。经典Ⅰ型与IgE及肥大细胞等相关，Ⅱ型涉及针对细胞或组织相关抗原的抗体，Ⅲ型与免疫复合物相关，Ⅳ型以T细胞介导为主。', ['能比较四类机制的主要介质。', '能避免把所有超敏反应都归为IgE介导。'], Q('经典Ⅳ型超敏反应主要由哪类免疫机制介导？', 'T细胞介导', ['IgE与肥大细胞介导', 'IgG或IgM针对细胞表面抗原的作用', '可溶性免疫复合物沉积介导'], 'Ⅳ型以T细胞效应为主，与前三类典型抗体相关机制不同。'), Q('教学机制图显示免疫复合物沉积并激活炎症，最符合经典哪一型超敏反应？', 'Ⅲ型', ['Ⅰ型', 'Ⅱ型', 'Ⅳ型'], 'Ⅲ型的典型机制是可溶性抗原抗体复合物形成、沉积及引发相关炎症；实际疾病可有机制重叠。'), [(4, '抗体结构和效应有助于理解抗体相关超敏反应'), (7, 'T细胞效应用于理解Ⅳ型机制')]), ('免疫缺陷与肿瘤免疫的基本框架', '免疫病理', '免疫相关性疾病的发生原理', '免疫缺陷可源于遗传因素或后天获得性原因，不同受损环节造成不同功能问题。免疫系统能够识别某些肿瘤相关变化，肿瘤也可通过多种途径逃避免疫作用。', ['能区分遗传性与获得性免疫缺陷。', '能说明肿瘤免疫识别与逃逸并存。'], Q('因后天因素导致免疫功能受损，通常归为哪类免疫缺陷？', '继发性免疫缺陷', ['所有情况均属原发遗传性免疫缺陷', '正常免疫记忆形成', '特定抗原的生理性免疫耐受'], '继发性免疫缺陷来自后天原因；分类需结合具体受损环节与证据。'), Q('肿瘤细胞降低抗原呈递或形成抑制性局部环境，可产生什么影响？', '帮助部分肿瘤细胞逃避免疫清除', ['证明肿瘤抗原不可能被任何免疫细胞识别', '增强所有T细胞对肿瘤细胞的抗原特异识别', '只改变肿瘤血管而与免疫识别无关'], '抗原呈递和微环境改变是免疫逃逸的可能环节，不等于取消所有免疫识别。'), [(6, '抗原呈递是理解肿瘤识别和逃逸的基础'), (7, '免疫效应分工用于理解不同缺陷和逃逸机制')]), ('主动免疫、被动免疫与检测边界', '免疫应用', '免疫学技术的原理及其应用', '主动免疫依赖机体形成应答，被动免疫提供已有抗体等效应成分，起效与持续特点不同。免疫检测测量特定靶标，结果受方法学和背景影响，不能直接等同于全部免疫功能。', ['能区分主动与被动免疫。', '能说明抗体检测的证据边界。'], Q('直接提供已制备的特异性抗体，在免疫学分类上主要属于什么？', '被动免疫', ['依赖自身新建应答的主动免疫', '胸腺内自身反应性T细胞的阴性选择', 'B细胞在生发中心发生的亲和力成熟'], '被动免疫把已有的效应成分给予受体，不以受体自行产生初次应答为起点。'), Q('某检测报告存在针对一个抗原的抗体，单凭这一结果不能推出什么？', '对所有相关感染在任何条件下都具有完全保护', ['检出结果与该检测靶标有关', '检测有其方法学范围', '解释结果需要了解背景'], '抗体存在不等于保护的绝对充分条件；浓度、功能、时间和病原变化等均可能影响意义。'), [(8, '主动免疫与记忆形成需要B细胞应答基础'), (4, '被动免疫和抗体测定涉及抗体效应', 'soft')])]
